input.command:
mkdir -p /tmp/funnel_acc && cat > /tmp/funnel_acc/events.jsonl <<'EOF'
{"user_id": "u1", "event": "visit", "timestamp": "2026-10-06T10:00:00"}
{"user_id": "u1", "event": "signup", "timestamp": "2026-10-06T11:00:00"}
{"user_id": "u2", "event": "visit", "timestamp": "2026-10-06T10:30:00"}
{"user_id": "u3", "event": "visit", "timestamp": "2026-10-06T11:00:00"}
{"user_id": "u3", "event": "signup", "timestamp": "2026-10-06T11:00:30"}
{"user_id": "u4", "event": "visit", "timestamp": "2026-10-06T09:59:30"}
{"user_id": "u4", "event": "signup", "timestamp": "2026-10-06T10:00:15"}
{"user_id": "u4", "event": "visit", "timestamp": "2026-10-06T10:00:30"}
EOF
rm -f /tmp/funnel_acc/events.sqlite
python -m funnel import /tmp/funnel_acc/events.jsonl --db /tmp/funnel_acc/events.sqlite
echo "--- windowed:"
python -m funnel report --db /tmp/funnel_acc/events.sqlite --visit-from 2026-10-06T10:00:00 --visit-before 2026-10-06T11:00:00; echo "rc=$?"
echo "--- windowed + within 60:"
python -m funnel report --db /tmp/funnel_acc/events.sqlite --visit-from 2026-10-06T10:00:00 --visit-before 2026-10-06T11:00:00 --within-seconds 60; echo "rc=$?"
echo "--- no window:"
python -m funnel report --db /tmp/funnel_acc/events.sqlite; echo "rc=$?"

